<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\JudgeMergeService;
Auth::requireSuperAdmin();$pdo=Database::connection();$q=trim((string)($_GET['q']??''));$keep=(int)($_GET['keep_id']??$_POST['keep_id']??0);$remove=(int)($_GET['remove_id']??$_POST['remove_id']??0);$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');if(strtoupper(trim((string)($_POST['confirmation']??'')))!=='MERGE JUDGE')throw new RuntimeException('Type MERGE JUDGE to confirm.');$done=JudgeMergeService::merge($pdo,$keep,$remove,(int)(Auth::user()['id']??0));$notice='Judge profiles merged. Scoring history now uses '.$done['kept']['full_name'].'.';$remove=0;}catch(Throwable $e){$error=$e->getMessage();}}
$rows=[];if($q!==''){$s=$pdo->prepare("SELECT id,judge_code,full_name,display_name,country,email,phone,instagram,status FROM bdc_judges WHERE LOWER(full_name) LIKE LOWER(:q1) OR LOWER(COALESCE(display_name,'')) LIKE LOWER(:q2) OR LOWER(COALESCE(judge_code,'')) LIKE LOWER(:q3) OR LOWER(COALESCE(email,'')) LIKE LOWER(:q4) OR LOWER(COALESCE(instagram,'')) LIKE LOWER(:q5) ORDER BY LOWER(full_name),id LIMIT 100");$v='%'.$q.'%';$s->execute(['q1'=>$v,'q2'=>$v,'q3'=>$v,'q4'=>$v,'q5'=>$v]);$rows=$s->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Merge Judges | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4" style="max-width:1100px"><a href="./">← Judge Directory</a><h1 class="h3 mt-3">Merge Duplicate Judges</h1><p class="text-muted">Keeps one profile, moves its J&amp;J and Dance Cup assignments, preserves scoring history and removes only the duplicate profile.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><form method="get" class="card card-body mb-3"><div class="input-group"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search judge name, code, email or Instagram"><button class="btn btn-dark">Search</button></div><small class="text-muted mt-2">Search is case-insensitive.</small></form><?php if($rows):?><div class="table-responsive card mb-3"><table class="table mb-0"><thead><tr><th>Judge</th><th>Contact</th><th>Choose</th></tr></thead><tbody><?php foreach($rows as $j):?><tr><td><strong><?=e($j['display_name']?:$j['full_name'])?></strong><br><code><?=e($j['judge_code'])?></code></td><td><?=e($j['email']?:$j['phone']?:$j['instagram']?:'—')?></td><td><a class="btn btn-sm btn-success" href="?q=<?=urlencode($q)?>&amp;keep_id=<?=(int)$j['id']?>&amp;remove_id=<?=$remove?>">Keep</a> <a class="btn btn-sm btn-outline-danger" href="?q=<?=urlencode($q)?>&amp;keep_id=<?=$keep?>&amp;remove_id=<?=(int)$j['id']?>">Duplicate</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($keep&&$remove&&$keep!==$remove):?><form method="post" class="card card-body border-danger"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="keep_id" value="<?=$keep?>"><input type="hidden" name="remove_id" value="<?=$remove?>"><label class="form-label">Type <strong>MERGE JUDGE</strong></label><input class="form-control mb-3" name="confirmation" required><button class="btn btn-danger" onclick="return confirm('Merge these judge profiles and preserve all scoring history?')">Merge Judge Profiles</button></form><?php endif;?></main></body></html>
